const categories={nomade:'women',crystal:'women',ysly:'men',myslf:'men',manblack:'men',epic:'men',spice:'men',imagination:'men',paradise:'men',tonka:'unisex',vibrato:'unisex',mango:'unisex',crush:'unisex',gucci:'men'}; products.forEach(p=>p.category=categories[p.id]);
const $=s=>document.querySelector(s);let filtered=[...products],current=0,filter='all',gridMode=true,selected=null,selectedSize=50,toastTimer;
let bag=[];try{bag=JSON.parse(localStorage.getItem('fc-bag')||'[]').filter(x=>products.some(p=>p.id===x.id)&&[30,50].includes(x.size)&&Number.isInteger(x.qty)&&x.qty>0).map(x=>({...x,qty:Math.min(x.qty,99)}))}catch{}
const price=size=>size===30?60:90;
function render(){const root=$('#carousel');const activeIds=new Set(filtered.map(p=>p.id));root.querySelectorAll('.perfume-card').forEach(c=>{if(!activeIds.has(c.dataset.id))c.remove()});filtered.forEach((p,i)=>{let delta=i-current;if(delta>filtered.length/2)delta-=filtered.length;if(delta< -filtered.length/2)delta+=filtered.length;let card=root.querySelector('[data-id='+p.id+']');const fresh=!card;if(fresh){card=document.createElement('button');card.dataset.id=p.id;card.className='perfume-card';}card.setAttribute('aria-label',`عرض ${p.name}`);card.innerHTML=`<img src="assets/${p.image}.png" alt="${p.name}" loading="${Math.abs(delta)<2?'eager':'lazy'}"><div class="card-caption"><small>FRAGRANT CLOUD · ${p.group.toUpperCase()}</small><strong>${p.name}</strong><span>اكتشف العطر · ابتداءً من 60 د.ل</span></div>`;card.style.transform=`translateX(${delta*250}px) translateZ(${-Math.abs(delta)*150}px) rotateY(${-delta*25}deg)`;card.style.opacity=Math.abs(delta)>2?'0':String(1-Math.abs(delta)*.24);card.style.zIndex=10-Math.abs(delta);card.style.pointerEvents=Math.abs(delta)>2?'none':'auto';card.tabIndex=Math.abs(delta)>2?-1:0;card.onclick=()=>{openProduct(p.id)};if(fresh){card.style.opacity='0';root.append(card);requestAnimationFrame(()=>{card.style.opacity=Math.abs(delta)>2?'0':String(1-Math.abs(delta)*.24)})}});$('#position').textContent=filtered.length?`${String(current+1).padStart(2,'0')} / ${String(filtered.length).padStart(2,'0')}`:'00 / 00';$('#noResults').hidden=!!filtered.length;$('#prev').disabled=$('#next').disabled=filtered.length<2;$('#grid').replaceChildren();if(gridMode)filtered.forEach(p=>{const b=document.createElement('button');b.className='grid-card';b.innerHTML=`<img src="assets/${p.image}.png" alt="${p.name}" loading="lazy"><h3 dir="ltr">${p.name}</h3><small>ابتداءً من 60 د.ل · اكتشف التفاصيل</small>`;b.onclick=()=>openProduct(p.id);$('#grid').append(b)})}
function applyFilter(){const query=$('#search').value.trim().toLowerCase();filtered=products.filter(p=>(filter==='all'||p.category===filter||p.group===filter)&&`${p.name} ${p.inspired}`.toLowerCase().includes(query));current=0;render()}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});applyFilter()});$('#search').oninput=applyFilter;
function step(n){if(!filtered.length)return;current=(current+n+filtered.length)%filtered.length;render()}$('#prev').onclick=()=>step(-1);$('#next').onclick=()=>step(1);$('#carousel').onkeydown=e=>{if(e.key==='ArrowLeft'){e.preventDefault();step(1)}if(e.key==='ArrowRight'){e.preventDefault();step(-1)}};
let startX=0;$('#carousel').addEventListener('touchstart',e=>{startX=e.changedTouches[0].clientX},{passive:true});$('#carousel').addEventListener('touchend',e=>{const dx=e.changedTouches[0].clientX-startX;if(Math.abs(dx)>45)step(dx<0?1:-1)},{passive:true});
$('#gridToggle').onclick=()=>{gridMode=!gridMode;$('#grid').hidden=!gridMode;$('#gridToggle').textContent=gridMode?'إخفاء الكل ▦':'عرض الكل ▦';$('#gridToggle').setAttribute('aria-expanded',String(gridMode));render()};
function openProduct(id){selected=products.find(p=>p.id===id);selectedSize=50;const p=selected;$('#productContent').innerHTML=`<div class="product-layout"><img src="assets/${p.image}.png" alt="${p.name}"><div class="product-info"><span class="eyebrow">FRAGRANT CLOUD · ${p.group.toUpperCase()}</span><h2>${p.name}</h2><span class="muted">مستوحى من <bdi>${p.inspired}</bdi></span><p>${p.text}</p><dl class="product-facts"><div><dt>الفئة</dt><dd>${({men:"رجالي",women:"نسائي",unisex:"مشترك"})[p.category]}</dd></div><div><dt>التركيز</dt><dd>Extrait de Parfum</dd></div><div><dt>30 مل</dt><dd>60 دينار ليبي</dd></div><div><dt>50 مل</dt><dd>90 دينار ليبي</dd></div></dl><span class="eyebrow">EXTRAIT DE PARFUM</span><div class="size-options" role="group" aria-label="اختيار الحجم"><button data-size="30">30 مل · 60 د.ل</button><button class="selected" data-size="50">50 مل · 90 د.ل</button></div><div class="price"><span id="productPrice">90</span> <small>دينار ليبي</small></div><button class="button gold" id="addToBag">أضف إلى حقيبة العطور <span>＋</span></button><p class="muted">منتج Fragrant Cloud مستوحى من العطر المذكور. الصور الجماعية تعرض أكثر من منتج؛ طلبك يخص العطر المحدد. يُؤكَّد التوفر والسعر عبر واتساب.</p></div></div>`;document.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{selectedSize=Number(b.dataset.size);document.querySelectorAll('[data-size]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});$('#productPrice').textContent=price(selectedSize)});$('#addToBag').onclick=()=>{const existing=bag.find(x=>x.id===p.id&&x.size===selectedSize);if(existing)existing.qty=Math.min(existing.qty+1,99);else bag.push({id:p.id,size:selectedSize,qty:1});saveBag();$('#productDialog').close();toast('تمت إضافة العطر إلى حقيبتك')};$('#productDialog').showModal()}
function saveBag(){try{localStorage.setItem('fc-bag',JSON.stringify(bag))}catch{}$('#count').textContent=bag.reduce((a,x)=>a+x.qty,0)}
function renderBag(){const root=$('#bagItems');root.replaceChildren();if(!bag.length)root.innerHTML='<p>حقيبتك تنتظر توقيعك العطري. اختر عطرك من الكتالوج.</p>';bag.forEach((x,i)=>{const p=products.find(p=>p.id===x.id),row=document.createElement('div');row.className='bag-row';row.innerHTML=`<img src="assets/${p.image}.png" alt="${p.name}"><div><strong dir="ltr">${p.name}</strong><small>${x.size} مل · ${price(x.size)*x.qty} د.ل</small><div class="qty"><button aria-label="تقليل كمية ${p.name}" data-minus>−</button><span>${x.qty}</span><button aria-label="زيادة كمية ${p.name}" data-plus>+</button></div></div><button data-remove aria-label="حذف ${p.name}">حذف</button>`;row.querySelector('[data-remove]').onclick=()=>{bag.splice(i,1);saveBag();renderBag()};row.querySelector('[data-minus]').onclick=()=>{if(x.qty>1)x.qty--;else bag.splice(i,1);saveBag();renderBag()};row.querySelector('[data-plus]').onclick=()=>{x.qty=Math.min(x.qty+1,99);saveBag();renderBag()};root.append(row)});const total=bag.reduce((s,x)=>s+price(x.size)*x.qty,0);$('#bagTotal').textContent=bag.length?`المجموع: ${total} دينار ليبي`:'';$('#checkout').hidden=!bag.length;$('#checkout').style.display=bag.length?'inline-flex':'none';const message='مرحبًا Fragrant Cloud، أود طلب:\n'+bag.map(x=>`${products.find(p=>p.id===x.id).name} — ${x.size} مل × ${x.qty} — ${price(x.size)*x.qty} د.ل`).join('\n')+`\nالمجموع: ${total} د.ل\nيرجى تأكيد التوفر والسعر وتفاصيل التوصيل.`;$('#checkout').href='https://wa.me/218929904411?text='+encodeURIComponent(message)}
$('#openBag').onclick=()=>{renderBag();$('#bagDialog').showModal()};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('pending');observer.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.reveal').forEach(x=>{x.classList.add('pending');observer.observe(x)});$('#year').textContent=new Date().getFullYear();saveBag();render();
